CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, case_id TEXT NOT NULL, label TEXT, created_at INTEGER NOT NULL, event_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'created', premium INTEGER NOT NULL DEFAULT 0, premium_answer TEXT, duration_min INTEGER NOT NULL DEFAULT 90, vars TEXT NOT NULL, secrets TEXT NOT NULL, join_code TEXT NOT NULL UNIQUE, org_code TEXT NOT NULL UNIQUE, org_token TEXT, test_mode INTEGER NOT NULL DEFAULT 0, opened_at INTEGER, started_at INTEGER, ended_at INTEGER, max_teams INTEGER, logo TEXT);
CREATE TABLE IF NOT EXISTS teams (id TEXT PRIMARY KEY, session_id TEXT NOT NULL, name TEXT NOT NULL, token TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, core_at INTEGER, solved_at INTEGER, penalty_min INTEGER NOT NULL DEFAULT 0, wrong INTEGER NOT NULL DEFAULT 0, last_attempt_at INTEGER, last_result TEXT, tips TEXT NOT NULL DEFAULT '[]', act2_at INTEGER, view_token TEXT, UNIQUE (session_id, name));
CREATE TABLE IF NOT EXISTS attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, team_id TEXT NOT NULL, at INTEGER NOT NULL, payload TEXT NOT NULL, correct INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS viewers (token TEXT PRIMARY KEY, team_id TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_teams_session ON teams(session_id);
CREATE INDEX IF NOT EXISTS idx_attempts_team ON attempts(team_id);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, token TEXT NOT NULL, created_at INTEGER NOT NULL, status TEXT NOT NULL, paket TEXT NOT NULL, teams INTEGER NOT NULL, amount_cents INTEGER NOT NULL, event_date TEXT NOT NULL, vars TEXT NOT NULL, contact TEXT NOT NULL, logo TEXT, stripe_session TEXT, session_id TEXT, paid_at INTEGER, shipped_at INTEGER);
CREATE TABLE IF NOT EXISTS stats_teams (session_id TEXT NOT NULL, team_no INTEGER NOT NULL, recorded_at INTEGER NOT NULL, case_id TEXT, premium INTEGER, test_mode INTEGER, duration_min INTEGER, teams_in_round INTEGER, stage_reached INTEGER, core_min REAL, act2_min REAL, solved_min REAL, attempts INTEGER, wrong INTEGER, penalty_min INTEGER, wrong_by_q TEXT, hints_akt1 INTEGER, hints_akt2 INTEGER, viewers INTEGER, PRIMARY KEY (session_id, team_no));
